def diagnose_text(text: str, *, confidence: float = 0.7) -> List[ComponentDiagnosis]:
    lowered = text.lower()
    diagnoses: List[ComponentDiagnosis] = []
    for failure_mode, keywords in KEYWORD_FAILURES.items():
        matched = [keyword for keyword in keywords if keyword in lowered]
        if not matched:
            continue
        for component in FAILURE_ROUTES[failure_mode]:
            spec = COMPONENT_SPECS[component]
            diagnoses.append(
                ComponentDiagnosis(
                    component=component,
                    failure_mode=failure_mode,
                    confidence=confidence,
                    evidence=f"Matched keywords: {', '.join(matched)}",
                    suggested_paths=spec.config_paths,
                    suggested_metrics=spec.metrics,
                    patch_strategy=spec.patch_strategies[0] if spec.patch_strategies else None,
                )
            )
    return _dedupe_diagnoses(diagnoses)


def diagnose_report(report: Any) -> List[ComponentDiagnosis]:
    evidence_parts: List[str] = []
    for result in getattr(report, "results", []) or []:
        evidence_parts.append(str(getattr(result, "transcript", "")))
        evidence_parts.append(_jsonish(getattr(result, "evaluation", None)))
        evidence_parts.append(_jsonish(getattr(result, "messages", None)))
        evidence_parts.append(_jsonish(getattr(result, "tool_calls", None)))
        evidence_parts.append(_jsonish(getattr(result, "events", None)))
        evidence_parts.append(_jsonish(getattr(result, "metadata", None)))
    text = "\n".join(part for part in evidence_parts if part)
    diagnoses = diagnose_text(text)
    if not diagnoses and text.strip():
        diagnoses.append(
            ComponentDiagnosis(
                component="evaluator",
                failure_mode="evaluation_gap",
                confidence=0.3,
                evidence="Report had evidence but no known failure keyword matched.",
                suggested_paths=COMPONENT_SPECS["evaluator"].config_paths,
                suggested_metrics=COMPONENT_SPECS["evaluator"].metrics,
                patch_strategy="add component-specific eval coverage",
            )
        )
    return diagnoses


def diagnose_agent_report_evaluation(
    evaluation: Any,
    *,
    failing_threshold: float = 0.85,
    confidence: float = 0.85,
) -> List[ComponentDiagnosis]:
    payload = _model_to_plain(evaluation)
    diagnoses: List[ComponentDiagnosis] = []
    if not isinstance(payload, dict):
        return diagnoses

    for finding in _iter_findings(payload):
        metric_name = str(finding.get("metric", ""))
        finding_type = str(finding.get("type", ""))
        repair_hint = FINDING_REPAIR_HINTS.get(finding_type)
        failure_mode = (
            repair_hint.get("failure_mode") if repair_hint else None
        ) or METRIC_FAILURES.get(metric_name)
        score = _as_float(finding.get("score"))
        if score is not None and score >= failing_threshold and metric_name != "trial_reliability":
            continue
        if failure_mode:
            diagnoses.extend(
                _diagnoses_for_failure(
                    failure_mode,
                    confidence=confidence,
                    evidence=f"{metric_name}: {_jsonish(finding)}",
                    metadata={"metric": metric_name, "finding": finding},
                    suggested_paths=repair_hint.get("suggested_paths") if repair_hint else None,
                    patch_strategy=repair_hint.get("patch_strategy") if repair_hint else None,
                )
            )

    for metric in _iter_metrics(payload):
        metric_name = str(metric.get("name", ""))
        failure_mode = METRIC_FAILURES.get(metric_name)
        score = _as_float(metric.get("score", metric.get("output")))
        if failure_mode is None or score is None or score >= failing_threshold:
            continue
        diagnoses.extend(
            _diagnoses_for_failure(
                failure_mode,
                confidence=max(0.4, min(confidence, 1.0 - score + 0.2)),
                evidence=(
                    f"{metric_name} score {score:.2f} below "
                    f"threshold {failing_threshold:.2f}: {metric.get('reason', '')}"
                ),
                metadata={"metric": metric_name, "score": score, "metric_result": metric},
            )
        )

    return _dedupe_diagnoses(diagnoses)


def relevant_search_paths(
    search_space: Dict[str, List[Any]],
    diagnoses: Sequence[ComponentDiagnosis],
) -> Set[str]:
    if not diagnoses:
        return set(search_space.keys())

    prefixes: Set[str] = set()
    for diagnosis in diagnoses:
        prefixes.update(diagnosis.suggested_paths)
        prefixes.update(COMPONENT_SPECS.get(diagnosis.component, COMPONENT_SPECS["custom"]).config_paths)
        prefixes.add(diagnosis.component)

    matched = {
        path
        for path in search_space
        if any(path == prefix or path.startswith(f"{prefix}.") for prefix in prefixes)
    }
    # Harness-layer locality (Phase 4, HarnessFix anti-broad-patch rule): layer
    # scoping NARROWS the component-scoped set; it never widens it, and an
    # empty intersection degrades to the component-scoped set rather than to
    # everything. Untagged diagnoses reproduce the legacy behavior exactly.
    layers = {
        getattr(diagnosis, "harness_layer", None)
        for diagnosis in diagnoses
        if getattr(diagnosis, "harness_layer", None)
    }
    if layers:
        layer_prefixes: Set[str] = set()
        for layer in layers:
            layer_prefixes.update(HARNESS_LAYER_PATH_PREFIXES.get(layer, ()))
        layer_matched = {
            path
            for path in matched
            if any(path == p or path.startswith(f"{p}.") for p in layer_prefixes)
        }
        if layer_matched:
            return layer_matched
    return matched or set(search_space.keys())


def _diagnoses_for_failure(
    failure_mode: FailureMode,
    *,
    confidence: float,
    evidence: str,
    metadata: Optional[Dict[str, Any]] = None,
    suggested_paths: Optional[Sequence[str]] = None,
    patch_strategy: Optional[str] = None,
) -> List[ComponentDiagnosis]:
    diagnoses: List[ComponentDiagnosis] = []
    for component in FAILURE_ROUTES[failure_mode]:
        spec = COMPONENT_SPECS[component]
        diagnoses.append(
            ComponentDiagnosis(
                component=component,
                failure_mode=failure_mode,
                confidence=confidence,
                evidence=evidence,
                suggested_paths=_merge_unique(spec.config_paths, suggested_paths or []),
                suggested_metrics=spec.metrics,
                patch_strategy=patch_strategy or (spec.patch_strategies[0] if spec.patch_strategies else None),
                metadata=metadata or {},
            )
        )
    return diagnoses


def _iter_findings(payload: Dict[str, Any]):
    for finding in payload.get("findings", []) or []:
        if isinstance(finding, dict):
            yield finding
    for case in payload.get("cases", []) or []:
        if not isinstance(case, dict):
            continue
        for finding in case.get("findings", []) or []:
            if isinstance(finding, dict):
                yield finding
        for metric in case.get("metrics", []) or []:
            if not isinstance(metric, dict):
                continue
            details = metric.get("details")
            if not isinstance(details, dict):
                continue
            for finding in details.get("findings", []) or []:
                if isinstance(finding, dict):
                    yield finding


def _iter_metrics(payload: Dict[str, Any]):
    for case in payload.get("cases", []) or []:
        if not isinstance(case, dict):
            continue
        for metric in case.get("metrics", []) or []:
            if isinstance(metric, dict):
                yield metric


def _as_float(value: Any) -> Optional[float]:
    if isinstance(value, bool):
        return 1.0 if value else 0.0
    if isinstance(value, (int, float)):
        return float(value)
    return None


def _dedupe_diagnoses(diagnoses: Iterable[ComponentDiagnosis]) -> List[ComponentDiagnosis]:
    best: Dict[tuple[str, str], ComponentDiagnosis] = {}
    for diagnosis in diagnoses:
        key = (diagnosis.component, diagnosis.failure_mode)
        if key not in best or diagnosis.confidence > best[key].confidence:
            best[key] = diagnosis
    return sorted(
        best.values(),
        key=lambda item: (item.confidence, item.component, item.failure_mode),
        reverse=True,
    )


def _merge_unique(*groups: Iterable[str]) -> List[str]:
    merged: List[str] = []
    seen: Set[str] = set()
    for group in groups:
        for item in group:
            if item not in seen:
                merged.append(item)
                seen.add(item)
    return merged


def _jsonish(value: Any) -> str:
    if value is None:
        return ""
    try:
        if hasattr(value, "model_dump"):
            value = value.model_dump()
        return json.dumps(value, default=str)
    except Exception:
        return str(value)


def _model_to_plain(value: Any) -> Any:
    if hasattr(value, "model_dump"):
        value = value.model_dump()
    elif hasattr(value, "dict"):
        value = value.dict()
    if isinstance(value, list):
        return [_model_to_plain(item) for item in value]
    if isinstance(value, tuple):
        return [_model_to_plain(item) for item in value]
    if isinstance(value, dict):
        return {key: _model_to_plain(item) for key, item in value.items()}
    if hasattr(value, "__dict__"):
        return {key: _model_to_plain(item) for key, item in vars(value).items()}
    return value
